head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[bigDecimal > M > minus]<br/>현재 bigDecimal 데이터에서 입력받은 bigDecimal 데이터를 빼서 결과를 반환합니다.",
    "validation" : [
        "bigDecimal(필수) 파라미터로 뺄셈을 수행할 bigDecimal 데이터를 설정할 수 있어야 합니다.",
        "뺄셈 결과를 bigDecimal 타입으로 반환해야 합니다.",
        "피연산자가 빈 문자열에서 생성된 bigDecimal 인 경우 0 으로 대체하여 연산해야 합니다.",
        "연산 중 오류가 발생하면 NaN 을 나타내는 bigDecimal 을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_minus_onclick = function () {
    let a = $p.bigDecimal("222222222222222");
    let b = $p.bigDecimal("111111111111111");
    let ret = a.minus(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.minus(b) : " + ret.toString());
}



scwin.btn_minusEmpty_onclick = function () {
    let a = $p.bigDecimal("222222222222222");
    let b = $p.bigDecimal("");
    let ret = a.minus(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.minus('') : " + ret.toString());
}



scwin.btn_minusNaN_onclick = function () {
    let a = $p.bigDecimal("abc");
    let b = $p.bigDecimal("111111111111111");
    let ret = a.minus(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a('abc').minus(b) : " + ret.toString());
}
